call_args.script:
cd /app && cat > /tmp/verify_default.go << 'EOF'
package main
import (
	"fmt"
	"github.com/cloudwego/kitex/pkg/rpcinfo"
	"github.com/cloudwego/kitex/transport"
)
func main() {
	c := rpcinfo.NewRPCConfig()
	if c.TransportProtocol() == transport.Framed {
		fmt.Println("✅ Default Protocol: Framed")
	} else {
		fmt.Printf("❌ Default Protocol: %v (expected Framed)\n", c.TransportProtocol())
	}
}
EOF
go run /tmp/verify_default.go

